function evaluateProperty({ api /*, helpers */ }) {
  // Lookup/Composite なので results に配列が入る想定
  const recs = api?.data?.look_up_department?.results ?? [];
  if (!Array.isArray(recs) || recs.length === 0) return [];

  const getFieldValue = (field) => (
    field?.value?.value ?? field?.value ?? field?.displayValue ?? ""
  );

  // 必要なら安全なソート（affiliation_code 降順の例）
  const sorted = [...recs].sort((a, b) => {
    const ax = getFieldValue(a?.affiliation_code).toString();
    const bx = getFieldValue(b?.affiliation_code).toString();
    return bx.localeCompare(ax, "ja");
  });

  const items = sorted.map((rec) => {
    const sysId = getFieldValue(rec?.sys_id);
    const n1 = getFieldValue(rec?.department_name_1);
    const n2 = getFieldValue(rec?.department_name_2);
    const n3 = getFieldValue(rec?.department_name_3);
    const n4 = getFieldValue(rec?.department_name_4);
    const n5 = getFieldValue(rec?.department_name_5);
    const code = getFieldValue(rec?.affiliation_code);

    const label = [n1, n2, n3, n4, n5].filter(Boolean).join(" ").trim();

    return {
      id: sysId || rec?._row_data?.uniqueValue || "", // 念のため uniqueValue もフォールバック
      label,
      sublabel: code
    };
  }).filter(x => x.id); // id 無しは除外

  return items;
}
